	static Transformation smethod_102(Vector3D vector3D_0, clsRobotic clsRobotic_0, Vector3D vector3D_1)
	{
		vector3D_1.Normalize();
		vector3D_0.Normalize();
		if (!(vector3D_1 == vector3D_0))
		{
			if (!(vector3D_1 == vector3D_0 * -1.0))
			{
				Vector3D vector3D = Vector3D.Cross(vector3D_1, vector3D_0);
				vector3D.Normalize();
				double angleInRadians = Vector3D.AngleBetween(vector3D_1, vector3D_0);
				return new Rotation(angleInRadians, vector3D);
			}
			Vector3D vector3D2 = Vector3D.AxisX;
			if (Math.Abs(Vector3D.Dot(vector3D_1, vector3D2)) > 0.9)
			{
				vector3D2 = Vector3D.AxisY;
			}
			return new Rotation(Math.PI, vector3D2);
		}
		return Transformation.CreateIdentity();
	}

