	static double[,] smethod_157(double[,] double_0, double[,] double_1)
	{
		int length = double_1.GetLength(0);
		int length2 = double_1.GetLength(1);
		int length3 = double_0.GetLength(1);
		double[,] array = new double[length, length3];
		for (int i = 0; i < length; i++)
		{
			for (int j = 0; j < length3; j++)
			{
				for (int k = 0; k < length2; k++)
				{
					array[i, j] += double_1[i, k] * double_0[k, j];
				}
			}
		}
		return array;
	}

	static void smethod_158(ref System.Drawing.Point point_0, ref System.Drawing.Point point_1)
	{
