			int x2 = Math.Max(point_1.X, point_0.X);
			int y2 = Math.Max(point_1.Y, point_0.Y);
			point_1.X = x;
			point_1.Y = y;
			point_0.X = x2;
			point_0.Y = y2;
		}
		catch (Exception)
