	static ICurve smethod_175(Sketcher2D sketcher2D_0, ICurve icurve_0)
	{
		if (icurve_0 is devDept.Eyeshot.Entities.Line)
		{
			devDept.Eyeshot.Entities.Line line = new devDept.Eyeshot.Entities.Line(icurve_0.StartPoint, icurve_0.EndPoint);
			Vector3D vector3D = new Vector3D(line.StartPoint, line.EndPoint);
			vector3D.Normalize();
			line.EndPoint += vector3D * sketcher2D_0.double_0;
			Vector3D vector3D2 = new Vector3D(line.EndPoint, line.StartPoint);
			vector3D2.Normalize();
			line.StartPoint += vector3D2 * sketcher2D_0.double_0;
			icurve_0 = line;
		}
		return icurve_0;
	}

