	static void smethod_177(clsEditorV2 clsEditorV2_0, devDept.Eyeshot.Entities.Line line_0)
	{
		Point2D point2D = clsItem.frmEditorV2.viewport.CurrentSketch.Plane.Project(line_0.StartPoint);
		Point2D point2D2 = clsItem.frmEditorV2.viewport.CurrentSketch.Plane.Project(line_0.EndPoint);
		if (Math.Abs(point2D.X - point2D2.X) < 1E-09)
		{
			clsItem.frmEditorV2.viewport.CurrentSketch.AddConstraintVertical(line_0);
		}
		if (Math.Abs(point2D.Y - point2D2.Y) < 1E-09)
		{
			clsItem.frmEditorV2.viewport.CurrentSketch.AddConstraintHorizontal(line_0);
		}
	}

