	static void smethod_217(F_ProfileSim f_ProfileSim_0)
	{
		if (f_ProfileSim_0.int_1 == 0)
		{
			if (clsInit.appProfile.activeProfile.FirstItem != null && clsInit.appProfile.activeProfile.FirstItem.CalculationData.Count > 0)
			{
				int num = clsInit.cProfile.HowManyClamperInsideProfile(clsInit.appProfile.activeProfile.FirstItem, buProfileCalc.varProfileSettings.MachineLength);
				if (num <= 1)
				{
					clsInit.cProfile.AddWarningToProfile(buLangTranslate.preSentencesProfile.OnlyOneClamperIsCatchProfile, ref clsInit.appProfile.activeProfile.FirstItem);
					buString5.MessageBoxWarning(buLangTranslate.preSentencesProfile.OnlyOneClamperIsCatchProfile + " - " + buLangTranslate.preSentences.CheckYourParameter);
				}
			}
			if (clsInit.appProfile.activeProfile.SecondItem != null && clsInit.appProfile.activeProfile.SecondItem.CalculationData.Count > 0)
			{
				int num2 = clsInit.cProfile.HowManyClamperInsideProfile(clsInit.appProfile.activeProfile.SecondItem, buProfileCalc.varProfileSettings.MachineLength);
				if (num2 <= 1)
				{
					clsInit.cProfile.AddWarningToProfile(buLangTranslate.preSentencesProfile.OnlyOneClamperIsCatchProfile, ref clsInit.appProfile.activeProfile.SecondItem);
					buString5.MessageBoxWarning(buLangTranslate.preSentencesProfile.OnlyOneClamperIsCatchProfile + " - " + buLangTranslate.preSentences.CheckYourParameter);
				}
			}
			buProfileCalc.varProfileRunSettings.GhostClamper = f_ProfileSim_0.chk_ghostright.Checked;
			buProfileCalc.varProfileRunSettings.CollisionDetect = f_ProfileSim_0.chk_collisiondetect.Checked;
		}
		f_ProfileSim_0.int_1++;
	}

